#include <stdio.h>

#define MAX_SIZE 30
#define MAX_ROWS 30 + 1
#define MAX_COLS 30 * 1000 + 1

#define MIN(a,b) a < b ? a : b

int getResult(int n, int* nums);

int main()
{
	int n;
	scanf("%d", &n);

	int nums[MAX_SIZE];
	for(int i=0; i<n; i++) {
		scanf("%d", &nums[i]);
	}

	printf("%d\n", getResult(n, nums));

	return 0;
}


int dp[MAX_ROWS][MAX_COLS] = {0};
int getResult(int n, int* nums)
{
	// 所有雨花石重量之和
	int sum = 0;
	for(int i=0; i<n; i++) {
		sum += nums[i];
	}

	// 如果重量之和不能整除2，则必然无法平分
	if(sum % 2 != 0) {
		return -1;
	}

	// 背包承重
	int bag = sum / 2;

	// 二维数组
	// 由于此处dp申请的内存过大，会造成栈内存溢出，因此将dp定义到全局
	//int dp[MAX_ROWS][MAX_COLS] = {0};

	// 初始化第一行，n是一个不可能的装满背包的物品数量
	// 注意dp[0][0]保持0
	for(int i=1; i<=bag; i++) {
		dp[0][i] = n;
	}

	for(int i=1; i<=n; i++) {
		int num = nums[i-1];

		for(int j=1; j<=bag; j++) {
			if(j < num) {
				dp[i][j] = dp[i-1][j];
			} else {
				dp[i][j] = MIN(dp[i-1][j], dp[i-1][j-num] + 1);
			}
		}
	}

	// 如果装满背包的最少物品数为n, 则说明没有平分方案，因为n个雨花石的重量之和为sumV，而背包的承重是bag = sumV // 2
	if(dp[n][bag] == n) {
		return -1;
	} else {
		return dp[n][bag];
	}
}
